// Suma una matriz de n x n guardada como un array plano, de dos maneras.
function medir(n, repeticiones) {
  const m = new Float64Array(n * n).fill(1);   // 8 bytes por elemento
  let suma = 0, porFilas = Infinity, porColumnas = Infinity;
  for (let r = 0; r < repeticiones; r++) {
    let t = performance.now();
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++) suma += m[i * n + j];   // lecturas consecutivas
    porFilas = Math.min(porFilas, performance.now() - t);

    t = performance.now();
    for (let j = 0; j < n; j++)
      for (let i = 0; i < n; i++) suma += m[i * n + j];   // saltos de n elementos
    porColumnas = Math.min(porColumnas, performance.now() - t);
  }
  return { porFilas, porColumnas, suma };
}

medir(256, 3);   // calentamiento: que el motor de JavaScript optimice antes de medir
let control = 0;
for (const n of [64, 256, 1024, 2048]) {
  const rep = n <= 256 ? 200 : 5;
  const r = medir(n, rep);
  control += r.suma;
  const ns = (ms) => ((ms * 1e6) / (n * n)).toFixed(2);
  console.log(`n=${n} (${(n * n * 8 / 1024).toLocaleString("es-AR")} KiB): por filas ${ns(r.porFilas)} ns/elemento, por columnas ${ns(r.porColumnas)} ns/elemento, cociente ${(r.porColumnas / r.porFilas).toFixed(1)}x`);
}
console.log("suma de control: " + control);
